CREATE TABLE IF NOT EXISTS words (id TEXT PRIMARY KEY, key TEXT UNIQUE NOT NULL, text TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 1, hidden INTEGER NOT NULL DEFAULT 0, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY, v TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate (ip TEXT PRIMARY KEY, last INTEGER NOT NULL, hits TEXT NOT NULL);
-- 15/10/2026 : sondage, questions, limite de mots par personne
CREATE TABLE IF NOT EXISTS wordsby (device TEXT PRIMARY KEY, n INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pvotes (poll TEXT NOT NULL, device TEXT NOT NULL, opt TEXT NOT NULL, PRIMARY KEY (poll, device, opt));
CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY, text TEXT NOT NULL, by TEXT NOT NULL DEFAULT '', votes INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0, answered INTEGER NOT NULL DEFAULT 0, pinned INTEGER NOT NULL DEFAULT 0, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS qvotes (qid TEXT NOT NULL, device TEXT NOT NULL, PRIMARY KEY (qid, device));
